INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·史家论述中的修德问答", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/jiuwudaishi-103-hidden-emperor-commentary/source.txt", "note": "《旧五代史》卷103·隐帝本纪·史家论述中的修德问答，段落 jiu-wudaishi-205deb4a7860-p002503；已核上下文及传主，纸本及异文待核。", "id": "dd49fbfd-501a-5ff2-9f8b-f1f3547724b2"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年闰月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/jiuwudaishi-103-intercalary-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年闰月，段落 jiu-wudaishi-205deb4a7860-p002488；已核上下文及传主，纸本及异文待核。", "id": "068ea84a-c89c-5a98-8aee-876100750e5d"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/jiuwudaishi-103-june-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年六月，段落 jiu-wudaishi-205deb4a7860-p002489；已核上下文及传主，纸本及异文待核。", "id": "d3a1f6f1-40df-5321-b3b6-226a38ab4035"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/jiuwudaishi-103-may-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年五月，段落 jiu-wudaishi-205deb4a7860-p002487；已核上下文及传主，纸本及异文待核。", "id": "885fdcc7-2e5f-5405-b4b9-9e5664fae361"}, {"title": "旧五代史·卷107·刘铢传·青州征召", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/jiuwudaishi-107-liu-zhu/source.txt", "note": "《旧五代史》卷107·刘铢传·青州征召，段落 jiu-wudaishi-205deb4a7860-p002580；已核上下文及传主，纸本及异文待核。", "id": "1ce9fb75-8509-584b-b3ac-94a6774cbff6"}, {"title": "资治通鉴·卷289·乾祐三年·闰月与六月等", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/tongjian-289-950-intercalary-month/source.txt", "note": "《资治通鉴》卷289·乾祐三年·闰月与六月等，段落 zizhi-tongjian-a63549944a71-p003429；已核上下文及传主，纸本及异文待核。", "id": "34e5229e-bf1a-5a50-b15a-3287f46ac4fa"}, {"title": "新五代史·卷30·史弘肇传·将相宴会冲突", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/xinwudaishi-030-shi-banquets/source.txt", "note": "《新五代史》卷30·史弘肇传·将相宴会冲突，段落 xin-wudaishi-b08f244b9241-p001097；已核上下文及传主，纸本及异文待核。", "id": "32d3e3c3-6077-56ef-9f23-339e7b4074b6"}, {"title": "资治通鉴·卷289·乾祐三年·四月、五月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/tongjian-289-950-spring-government/source.txt", "note": "《资治通鉴》卷289·乾祐三年·四月、五月及追述，段落 zizhi-tongjian-a63549944a71-p003428；已核上下文及传主，纸本及异文待核。", "id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"title": "宋史·卷261·郭琼传·后汉任职", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/songshi-261-guo-qiong-han/source.txt", "note": "《宋史》卷261·郭琼传·后汉任职，段落 songshi-9c6e46fee832-p058012；已核上下文及传主，纸本及异文待核。", "id": "858f6f3b-4c99-57df-97e5-7fbdea9f2b8c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "刘承勋", "aliases": ["劉承勛", "劉承勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘承祐的弟弟。950年五月以山南西道节度使身份被任命为开封尹，加兼中书令；《资治通鉴》同时说明他实际尚未出阁。与947年已去世的刘承训分开，生卒年未载。", "biography": null, "status": "draft", "id": "3f17d043-13b1-5bdf-bd39-715c053074f4"}, {"name": "刘铢", "aliases": ["劉銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "陕地人，任河东左都押牙。947年刘知远任命他为河阳节度使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "bcd8da9c-9e21-53c2-a6be-7a6d37b61a32"}, {"name": "郭琼", "aliases": ["郭瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将领，曾任沂州刺史。950年正月奉命担任东路行营都部署，率禁军和齐州兵支援王万敢。《宋史》郭琼传记其为平州卢龙人，但对密州战事的叙述与通鉴不同，分别保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "2bb6c55b-0b36-5f0b-9c32-5bc865efa268"}, {"name": "郭超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "卫州刺史。《宋史》郭琼传记他与郭琼奉命率部屯青州，涉及后汉征召刘铢。该传没有单列行动纪日，《资治通鉴》相应段只列郭琼；生卒年未载。", "biography": null, "status": "draft", "id": "1f22772f-0b80-52c6-9bf6-389651d981c3"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "阎晋卿", "aliases": ["閻晉卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "忻州人，后汉客省使。949年正月河中军夜袭后汉营寨时，提醒将士可以凭黄纸甲在火光下辨认敌军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "cd541c62-d1b8-5017-afb5-ae81ba6585ac"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "阎氏（史弘肇妻）", "aliases": ["閻氏（史弘肇妻）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史弘肇的妻子。史书记她曾是酒家倡，即在酒家表演的歌伎。950年王章宴会上，史弘肇把苏逢吉关于阎姓的玩笑理解为讥讽妻子的出身。她是否出席宴会未载，名字和生卒年未载。", "biography": null, "status": "draft", "id": "d874abbf-e0bd-5d07-987c-0148832a0361"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "赵延乂", "aliases": ["趙延乂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵延乂，翰林天文、轮值者。", "biography": null, "status": "draft", "id": "6c04e553-0a04-5dbe-9236-85f04393f290"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "郭威辞行，劝刘承祐听取太后教导并信任旧臣", "start_year": 950, "end_year": 950, "time_original": "950年五月庚子", "dynasty": "五代十国", "description": "郭威辞行时劝刘承祐听取李太后的教导，亲近忠直、远离谗邪，信任苏逢吉、杨邠、史弘肇等旧臣，并表示愿尽力守边。刘承祐郑重致谢。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4b5c9f2b-bbde-53d5-8a84-4ec3cc4f56a6"}, {"title": "郭威到邺都后，命边将严守边境、不得出境侵掠", "start_year": 950, "end_year": 950, "time_original": "950年五月辞行到邺都后，具体到任日未载", "dynasty": "五代十国", "description": "郭威到邺都后，因河北困弊，要求边将严加防备、不得出境侵掠。契丹若入侵，就守坚固城寨，清空城外可被敌军利用的粮草等物资，等待对方。", "phases": [], "location_name": "邺都、河北边境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eaaecd27-ac12-531b-953c-3514f9316f1b"}, {"title": "后汉规定防御使、团练使非军务须先经观察使奏报", "start_year": 950, "end_year": 950, "time_original": "950年五月辛丑", "dynasty": "五代十国", "description": "后汉规定，防御使、团练使除军事事项外，不得自行直接奏报，应先报观察使，由其斟酌后上报朝廷。", "phases": [], "location_name": "后汉各州与朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9906fb78-b01c-569f-b00e-31b6cb01e57d"}, {"title": "刘承勋获任开封尹，加兼中书令", "start_year": 950, "end_year": 950, "time_original": "950年五月丙午", "dynasty": "五代十国", "description": "刘承勋获任开封尹，加兼中书令。", "phases": [], "location_name": "后汉朝廷、开封", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "65a92a7b-2123-5d80-a021-d667fed0722f"}, {"title": "后汉担心刘铢拒召，派郭琼率兵屯青州", "start_year": 950, "end_year": 950, "time_original": "950年五月刘铢庚戌入朝之前，具体部署日未载", "dynasty": "五代十国", "description": "后汉担心刘铢拒召，派郭琼率兵屯青州。", "phases": [], "location_name": "青州、平卢军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "80044322-0ea7-5c26-92b9-ad1195afa0d8"}, {"title": "刘铢设宴召郭琼，埋伏兵士准备杀他", "start_year": 950, "end_year": 950, "time_original": "950年五月刘铢入朝前，具体宴会日未载", "dynasty": "五代十国", "description": "刘铢设宴召郭琼，埋伏兵士准备杀他。", "phases": [], "location_name": "青州刘铢宴会场所", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2cd41734-2f0d-56e7-9350-2a291dca115c"}, {"title": "郭琼知道设伏，仍屏退随从从容赴宴", "start_year": 950, "end_year": 950, "time_original": "950年五月刘铢入朝前", "dynasty": "五代十国", "description": "郭琼知道设伏，仍屏退随从从容赴宴。", "phases": [], "location_name": "青州刘铢宴会场所", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b74a06ed-ae27-5667-8231-097ab52ff9c8"}, {"title": "郭琼向刘铢陈说利害，刘铢接诏后动身", "start_year": 950, "end_year": 950, "time_original": "950年五月庚戌入朝前，具体动身日未载", "dynasty": "五代十国", "description": "郭琼向刘铢陈说利害，刘铢接诏后动身。", "phases": [], "location_name": "青州至后汉京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c8571afb-d0a7-511a-8384-96d5431b14fa"}, {"title": "刘铢入朝", "start_year": 950, "end_year": 950, "time_original": "950年五月庚戌", "dynasty": "五代十国", "description": "刘铢入朝。", "phases": [], "location_name": "后汉京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "st