INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "郭威辞行时劝刘承祐听取李太后的教导，亲近忠直、远离谗邪，信任苏逢吉、杨邠、史弘肇等旧臣，并表示愿尽力守边。刘承祐郑重致谢。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：必无败失是郭威对旧臣的信任与劝告，不当后续不会失败的事实；太后被提到不证明她出席辞行。", "status": "draft", "id": "79adddbe-b28b-5fa5-b158-66a17b114e2a", "subject_id": "4b5c9f2b-bbde-53d5-8a84-4ec3cc4f56a6", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年五月庚子", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "380f437a-ac59-5f06-84bc-6ffb23283954", "subject_id": "4b5c9f2b-bbde-53d5-8a84-4ec3cc4f56a6", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭威：辞行时劝皇帝听取太后教导、亲近忠直、信任旧臣，并承诺守边。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "80e91125-7318-597d-8c03-ee5ddf3d5290", "subject_id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：辞行时劝皇帝听取太后教导、亲近忠直、信任旧臣，并承诺守边。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0ee33efa-0f0a-5290-aac6-1ddcca12ce85", "subject_id": "fb456569-89a7-598f-978b-837b1b5f517c", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘承祐：听取郭威辞行劝告，郑重致谢。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "6c95532b-da34-5857-98f1-7fce8001f476", "subject_id": "96b54cac-772d-54e8-b2de-975b3be49e85", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：听取郭威辞行劝告，郑重致谢。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：庚子，郭威辞行，言于帝曰：“太后从先帝久，多历天下事，陛下富于春秋，有事宜禀其教而行之。亲近忠直，放远谗邪，善恶之间，所宜明审。苏逢吉、杨邠、史弘肇皆先帝旧臣，尽忠徇国，愿陛下推心任之，必无败失。至于疆场之事，臣愿竭其愚驽，庶不负驱策。”帝敛容谢之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "48a5790a-5538-5ff5-b691-93eec84aa7d3", "subject_id": "c7720c93-fb87-5806-988a-fd1ac953e3f9", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭威到邺都后，因河北困弊，要求边将严加防备、不得出境侵掠。契丹若入侵，就守坚固城寨，清空城外可被敌军利用的粮草等物资，等待对方。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：威至鄴都，以河北困弊，戒边将谨守疆场，严守备，无得出侵掠，契丹入寇，则坚壁清野以待之。；核对说明：坚壁清野为备敌指令，不写成本段已经全线实施清野或打退新一次入侵。", "status": "draft", "id": "98ec045f-e964-56d7-8558-7a7a28c6e351", "subject_id": "eaaecd27-ac12-531b-953c-3514f9316f1b", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年五月辞行到邺都后，具体到任日未载", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：威至鄴都，以河北困弊，戒边将谨守疆场，严守备，无得出侵掠，契丹入寇，则坚壁清野以待之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "064f61be-3d4a-5fe3-a52c-86178807b522", "subject_id": "eaaecd27-ac12-531b-953c-3514f9316f1b", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：到邺都后要求边将严守边境，不得出境侵掠。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p022·原文件第27行", "note": "原文：威至鄴都，以河北困弊，戒边将谨守疆场，严守备，无得出侵掠，契丹入寇，则坚壁清野以待之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b297f617-f190-551e-aa87-2db39d5e1600", "subject_id": "4e45981a-4384-5a31-877f-7cd5ee88c1ce", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "description", "claim_text": "后汉规定，防御使、团练使除军事事项外，不得自行直接奏报，应先报观察使，由其斟酌后上报朝廷。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p023·原文件第28行", "note": "原文：辛丑，敕：“防御、团练使，自非军期，无得专奏事，皆先申观察使斟酌以闻。”；核对说明：军期按军事事项理解，保留例外，不写成任何情况都禁止直接奏报。", "status": "draft", "id": "cc9eb905-1366-5760-89a5-baad64a4cddd", "subject_id": "9906fb78-b01c-569f-b00e-31b6cb01e57d", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年五月辛丑", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p023·原文件第28行", "note": "原文：辛丑，敕：“防御、团练使，自非军期，无得专奏事，皆先申观察使斟酌以闻。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "19551ecf-e55f-561e-8b6e-8fbb5de38b59", "subject_id": "9906fb78-b01c-569f-b00e-31b6cb01e57d", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：下敕规定防御使、团练使的奏报程序。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p023·原文件第28行", "note": "原文：辛丑，敕：“防御、团练使，自非军期，无得专奏事，皆先申观察使斟酌以闻。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "22121928-1dcd-5e45-9848-a01c38a8be82", "subject_id": "b7ef871e-f2a1-5bf7-953e-6b2339b80655", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘承勋获任开封尹，加兼中书令。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：丙午，以皇弟山南西道节度使承勋为开封尹，加兼中书令，实未出阁。；核对说明：未出阁表示尚未出阁任事，不据此补年龄或已经实掌开封政务。承勋与承训字不同，后者947年已去世，不合并。", "status": "draft", "id": "c08a9cab-266c-5a87-900a-6f526c7af422", "subject_id": "65a92a7b-2123-5d80-a021-d667fed0722f", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年五月丙午", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：丙午，以皇弟山南西道节度使承勋为开封尹，加兼中书令，实未出阁。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "8912bea7-727e-5e65-a2f7-b546f0589cd1", "subject_id": "65a92a7b-2123-5d80-a021-d667fed0722f", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：任命弟弟刘承勋为开封尹，加兼中书令。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：丙午，以皇弟山南西道节度使承勋为开封尹，加兼中书令，实未出阁。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c555b021-212d-5c38-84c4-237445019f8e", "subject_id": "29070e5b-aa31-53e8-8b88-df4ab0b6695d", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘承勋：以山南西道节度使身份获任开封尹，加兼中书令。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：丙午，以皇弟山南西道节度使承勋为开封尹，加兼中书令，实未出阁。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "809e415c-daf8-5f09-b4f5-522c24dbd957", "subject_id": "3f17d043-13b1-5bdf-bd39-715c053074f4", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承勋：以山南西道节度使身份获任开封尹，加兼中书令。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：丙午，以皇弟山南西道节度使承勋为开封尹，加兼中书令，实未出阁。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "591f02ed-6a4b-5923-a78a-c4b4a54e2b0f", "subject_id": "77b00788-60b7-58c4-830c-cc76d098f88c", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日也记皇弟承勋任开封尹、兼中书令，并说明未出阁。", "citation": "《旧五代史》卷103·隐帝本纪·乾祐三年五月，段落 jiu-wudaishi-205deb4a7860-p002487；已核上下文及传主，纸本及异文待核。", "note": "原文：丙午，以皇弟興元節度承使勛為開封尹，加兼中書令，未出閣。；核对说明：兴元、山南西道职称对照；《旧五代史》电子本节度承使勋有转录字序问题，摘录原样保留，不据此另建承使勋人物。", "status": "draft", "id": "16c57c87-b9d7-5d3e-8a28-13024d59d7b4", "subject_id": "65a92a7b-2123-5d80-a021-d667fed0722f", "source_id": "885fdcc7-2e5f-5405-b4b9-9e5664fae361"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "刘承祐是刘承勋的兄长。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p024·原文件第29行", "note": "原文：以皇弟山南西道节度使承勋；核对说明：皇弟明确刘承勋是刘承祐的弟弟，因此刘承祐是其兄长；未据本句推同母。", "status": "draft", "id": "a9868638-cdba-5491-8e53-16b1d40cbca6", "subject_id": "28eea09f-8ae4-5d0d-9714-1892bf24e97c", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "description", "claim_text": "后汉担心刘铢拒召，派郭琼率兵屯青州。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p025·原文件第30行", "note": "原文：平卢节度使刘铢，贪虐恣横，朝廷欲征之，恐其拒命，因沂、密用兵于唐，遣前沂州刺史郭琼将兵屯青州。；核对说明：贪虐恣横为史书对刘铢的评价，借沂密用兵不另造本月新的完整对唐战役。部署与后续实际入朝分开。", "status": "draft", "id": "6517b862-01c4-599f-9094-7d285120fc93", "subject_id": "80044322-0ea7-5c26-92b9-ad1195afa0d8", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年五月刘铢庚戌入朝之前，具体部署日未载", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p025·原文件第30行", "note": "原文：平卢节度使刘铢，贪虐恣横，朝廷欲征之，恐其拒命，因沂、密用兵于唐，遣前沂州刺史郭琼将兵屯青州。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "fbc4c1fd-c492-5a93-a00e-d1d4b1b80a56", "subject_id": "80044322-0ea7-5c26-92b9-ad1195afa0d8", "source_id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘铢：朝廷想征召他，担心他拒命。", "citation": "卷289·乾祐三年（950年五月、闰月、六月及追述）·zztj-v289-y0950-p025·原文件第30行", "note": "原文：平